-- Curated layer: one row per non-cancelled order, joined to its customer and aggregated order lines.
CREATE OR REPLACE TABLE curated_orders AS SELECT o.order_id, CAST(o.order_ts AS TIMESTAMP_NTZ(6)) AS order_ts, o.status, o.amount, c.customer_id, c.name AS customer_name, c.country, COUNT(i.sku) AS item_lines, COALESCE(SUM(i.qty), 0) AS units, ROUND(SUM(i.qty * i.price), 2) AS items_value FROM orders o JOIN customers c ON c.customer_id = o.customer_id LEFT JOIN order_items i ON i.order_id = o.order_id WHERE o.status <> 'cancelled' GROUP BY o.order_id, o.order_ts, o.status, o.amount, c.customer_id, c.name, c.country;
